const choiceNumberSpan = document.getElementById("choiceNumber");
const resultSection = document.getElementById("resultSection");
const decklistOutput = document.getElementById("decklistOutput");
const firstPackSummaryDiv = document.getElementById("firstPackSummary");

// Set filters
const setFiltersContainer = document.getElementById("setFilters");
const selectAllSetsBtn = document.getElementById("selectAllSetsBtn");
const clearAllSetsBtn = document.getElementById("clearAllSetsBtn");
const setCountText = document.getElementById("setCountText");

// Card preview panel
const cardPreview = document.getElementById("cardPreview");

// --- 3) State ---------------------------------------------------
let currentChoiceIndex = 0; // 0 = first choice, 1 = second
let selectedPacks = [];
let usedPackIds = new Set();
let selectedSets = new Set(); // which sets are active in the pool
let lastOfferedPackIds = new Set(); // packs shown in the last choice screen

// For hover preview race-condition protection
let currentPreviewPackId = null;

// --- 4) Scryfall fetching (first-card data) ---------------------

async function fetchCardData(cardName) {
  try {
    const encoded = encodeURIComponent(cardName);
    const res = await fetch(
      `https://api.scryfall.com/cards/named?exact=${encoded}`
    );
    if (!res.ok) {
      console.warn("Scryfall lookup failed for:", cardName, res.status);
      return null;
    }
    return await res.json();
  } catch (err) {
    console.error("Error fetching card for:", cardName, err);
    return null;
  }
}

/**
 * Ensure we have first-card data for this pack, stored as pack.firstCardData:
 * {
 *   name, artUrl, imageUrl, oracleText, typeLine, manaCost
 * }
 */
async function ensureFirstCardData(pack) {
  if (pack.firstCardData) return pack.firstCardData;

  if (!pack.cards || !pack.cards.length) {
    pack.firstCardData = null;
    return null;
  }

  const firstCardName = pack.cards[0].name;
  const data = await fetchCardData(firstCardName);
  if (!data) {
    pack.firstCardData = null;
    return null;
  }

  const face =
    data.card_faces && data.card_faces[0] ? data.card_faces[0] : null;

  const artUrl =
    (data.image_uris && (data.image_uris.art_crop || data.image_uris.normal)) ||
    (face && face.image_uris && (face.image_uris.art_crop || face.image_uris.normal)) ||
    null;

  const imageUrl =
    (data.image_uris && data.image_uris.normal) ||
    (face && face.image_uris && face.image_uris.normal) ||
    artUrl ||
    null;

  const oracleText = face?.oracle_text || data.oracle_text || "";
  const typeLine = face?.type_line || data.type_line || "";
  const manaCost = face?.mana_cost || data.mana_cost || "";

  pack.firstCardData = {
    name: data.name || firstCardName,
    artUrl,
    imageUrl,
    oracleText,
    typeLine,
    manaCost
  };

  return pack.firstCardData;
}

/**
 * Apply first-card art as background to a pack element.
 */
async function ensurePackImage(pack, packElement) {
  const artDiv = packElement.querySelector(".pack-art");
  if (!artDiv) return;

  const firstCard = await ensureFirstCardData(pack);
  if (firstCard && firstCard.artUrl) {
    artDiv.style.backgroundImage = `url('${firstCard.artUrl}')`;
  }
}

// --- 5) Utility helpers -----------------------------------------

function shuffleArray(list) {
  const a = list.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function getRandomFromList(list, count) {
  const shuffled = shuffleArray(list);
  return shuffled.slice(0, Math.min(count, shuffled.length));
}

function uniqueColors(colors) {
  return Array.from(new Set(colors || []));
}

function getPackSetKey(pack) {
  return pack.set || "Custom";
}

function isPackInSelectedSets(pack) {
  const key = getPackSetKey(pack);
  if (selectedSets.size === 0) return false;
  return selectedSets.has(key);
}

function buildColorsHtml(pack) {
  if (!pack.colors || !pack.colors.length) return "";
  return `
    <div class="pack-colors">
      ${pack.colors
        .map((c) => `<span class="color-pip color-${c}">${c}</span>`)
        .join("")}
    </div>
  `;
}

function updateSelectedPackCount() {
  const count = PACKS.filter(isPackInSelectedSets).length;
  setCountText.textContent =
    `${count} pack${count === 1 ? "" : "s"} currently in pool.`;
}

// --- 6) Set filter menu -----------------------------------------

function initSetFilters() {
  const allSetKeys = [...new Set(PACKS.map(getPackSetKey))].sort();
  // default: all selected
  selectedSets = new Set(allSetKeys);

  setFiltersContainer.innerHTML = "";
  allSetKeys.forEach((setKey) => {
    const id = `set-filter-${setKey.replace(/[^a-zA-Z0-9_-]/g, "_")}`;
    const chip = document.createElement("label");
    chip.className = "set-filter-chip";
    chip.innerHTML = `
      <input type="checkbox" id="${id}" checked data-set-key="${setKey}" />
      <span>${setKey}</span>
    `;
    const checkbox = chip.querySelector("input");
    checkbox.addEventListener("change", () => {
      if (checkbox.checked) {
        selectedSets.add(setKey);
      } else {
        selectedSets.delete(setKey);
      }
      updateSelectedPackCount();
    });
    setFiltersContainer.appendChild(chip);
  });

  selectAllSetsBtn.addEventListener("click", () => {
    selectedSets = new Set(allSetKeys);
    setFiltersContainer
      .querySelectorAll("input[type='checkbox']")
      .forEach((cb) => (cb.checked = true));
    updateSelectedPackCount();
  });

  clearAllSetsBtn.addEventListener("click", () => {
    selectedSets.clear();
    setFiltersContainer
      .querySelectorAll("input[type='checkbox']")
      .forEach((cb) => (cb.checked = false));
    updateSelectedPackCount();
  });

  updateSelectedPackCount();
}

// --- 7) First pack summary --------------------------------------

function renderFirstPackSummary() {
  if (currentChoiceIndex === 0 || selectedPacks.length === 0) {
    firstPackSummaryDiv.style.display = "none";
    firstPackSummaryDiv.innerHTML = "";
    return;
  }

  const pack = selectedPacks[0];
  const setLabel = getPackSetKey(pack);

  firstPackSummaryDiv.style.display = "flex";
  firstPackSummaryDiv.innerHTML = `
    <span class="first-pack-summary-label">First Pack:</span>
    <span class="first-pack-summary-name">${pack.name}</span>
    <span class="first-pack-summary-set">${setLabel}</span>
    ${buildColorsHtml(pack)}
  `;
}

// --- 8) Card preview (hover) ------------------------------------

async function showCardPreviewForPack(pack) {
  currentPreviewPackId = pack.id;

  const firstCard = await ensureFirstCardData(pack);
  if (!firstCard || currentPreviewPackId !== pack.id) return;

  const { name, imageUrl, oracleText, typeLine, manaCost } = firstCard;

  const manaHtml = manaCost ? `<span class="card-preview-mana">${manaCost}</span>` : "";

  cardPreview.innerHTML = `
    <div class="card-preview-header">
      <span class="card-preview-name">${name}</span>
      ${manaHtml}
    </div>
    <div class="card-preview-type">${typeLine || ""}</div>
    <div class="card-preview-body">
      <div class="card-preview-image">
        ${
          imageUrl
            ? `<img src="${imageUrl}" alt="${name}" />`
            : ""
        }
      </div>
      <div class="card-preview-text">
        ${oracleText || "No rules text available."}
      </div>
    </div>
  `;

  cardPreview.style.display = "flex";
}

function hideCardPreview() {
  currentPreviewPackId = null;
  cardPreview.style.display = "none";
}

// --- 9) Rendering pack choices (with second-pack rules) ---------

function showPackChoices() {
  choicesSection.style.display = "block";
  resultSection.style.display = "none";
  choiceNumberSpan.textContent = currentChoiceIndex + 1;

  renderFirstPackSummary();

  let pool;

  if (currentChoiceIndex === 0) {
    // FIRST CHOICE:
    // any pack not previously used and in selected sets
    pool = PACKS.filter(
      (p) => !usedPackIds.has(p.id) && isPackInSelectedSets(p)
    );
  } else {
    // SECOND CHOICE:
    // your color rules based on the first pack,
    // and avoid re-offering the same packs shown in the first choice.
    const firstPack = selectedPacks[0];
    const firstColors = uniqueColors(firstPack.colors || []);
    const firstCount = firstColors.length;

    pool = PACKS.filter((p) => {
      if (usedPackIds.has(p.id)) return false;
      if (lastOfferedPackIds.has(p.id)) return false;
      if (!isPackInSelectedSets(p)) return false;

      const packColors = uniqueColors(p.colors || []);
      const packCount = packColors.length;
      if (packCount === 0) return false;

      // CASE 1: first pack is mono-colored
      // Second pack must be:
      //   - mono-colored (any color), OR
      //   - any pack that shares a color with the first pack
      if (firstCount === 1) {
        const isMono = packCount === 1;
        const sharesColor = packColors.some((c) => c === firstColors[0]);
        return isMono || sharesColor;
      }

      // CASE 2: first pack is two-color or three-color
      // Second pack must keep total colors < 4
      if (firstCount === 2 || firstCount === 3) {
        const union = new Set(firstColors);
        packColors.forEach((c) => union.add(c));
        return union.size < 4;
      }

      // CASE 3: first pack is four-color or five-color
      // Just use random packs (no extra color restriction)
      return true;
    });
  }

  const randomPacks = getRandomFromList(pool, 3);
  packChoicesDiv.innerHTML = "";

  if (randomPacks.length === 0) {
    packChoicesDiv.innerHTML = `
      <p style="color:#f97373; font-size:0.9rem;">
        No packs available with the current set filters and color rules.
        Try enabling more sets or restarting.
      </p>
    `;
    return;
  }

  // Track which packs are offered this time
  lastOfferedPackIds = new Set(randomPacks.map((p) => p.id));

  randomPacks.forEach((pack) => {
    const totalCards = pack.cards.reduce((sum, c) => sum + c.count, 0);
    const setLabel = getPackSetKey(pack);

    const div = document.createElement("div");
    div.className = "pack";
    div.innerHTML = `
      <div class="pack-art"></div>
      <div class="pack-content">
        <div class="pack-header">
          <div class="pack-title">${pack.name}</div>
          <div class="pack-tag">${setLabel}</div>
        </div>
        ${buildColorsHtml(pack)}
        ${
          pack.description
            ? `<div class="pack-description">${pack.description}</div>`
            : ""
        }
        <div class="pack-meta">
          <span>
            <span class="pack-meta-label">Cards</span>
            <span class="pack-meta-value">${totalCards}</span>
          </span>
          <span>
            <span class="pack-meta-label">Set</span>
            <span>${setLabel}</span>
          </span>
        </div>
      </div>
    `;

    // Click selects the pack
    div.addEventListener("click", () => handlePackChosen(pack));

    // Hover shows detailed first-card preview
    div.addEventListener("mouseenter", () => showCardPreviewForPack(pack));
    div.addEventListener("mouseleave", hideCardPreview);

    // Lazy-load first-card art for this pack
    ensurePackImage(pack, div);

    packChoicesDiv.appendChild(div);
  });
}

// --- 10) When a pack is chosen ----------------------------------

function handlePackChosen(pack) {
  selectedPacks.push(pack);
  usedPackIds.add(pack.id);

  hideCardPreview();

  if (currentChoiceIndex === 0) {
    currentChoiceIndex = 1;
    showPackChoices();
  } else {
    buildAndShowDecklist();
  }
}

// --- 11) Build combined decklist -------------------------------

function buildCombinedCardMap() {
  const cardMap = new Map(); // name -> count
  selectedPacks.forEach((pack) => {
    pack.cards.forEach((card) => {
      const prev = cardMap.get(card.name) || 0;
      cardMap.set(card.name, prev + card.count);
    });
  });
  return cardMap;
}

function buildAndShowDecklist() {
  const cardMap = buildCombinedCardMap();

  const lines = [];
  lines.push("// Combined Jumpstart Deck");
  lines.push(`// Pack 1: ${selectedPacks[0].name}`);
  lines.push(`// Pack 2: ${selectedPacks[1].name}`);
  lines.push("");

  const sortedCards = [...cardMap.entries()].sort((a, b) =>
    a[1] === b[1] ? a[0].localeCompare(b[0]) : b[1] - a[1]
  );

  sortedCards.forEach(([name, count]) => {
    lines.push(`${count} ${name}`);
  });

  decklistOutput.value = lines.join("\n");

  choicesSection.style.display = "none";
  resultSection.style.display = "block";
}

// Just card lines (for clipboard)
function buildPlainDecklistText() {
  const cardMap = buildCombinedCardMap();

  const sortedCards = [...cardMap.entries()].sort((a, b) =>
    a[1] === b[1] ? a[0].localeCompare(b[0]) : b[1] - a[1]
  );

  const lines = [];
  sortedCards.forEach(([name, count]) => {
    lines.push(`${count} ${name}`);
  });

  return lines.join("\n");
}

// --- 12) Clipboard copy -----------------------------------------

function fallbackCopyToClipboard(text) {
  const temp = document.createElement("textarea");
  temp.value = text;
  temp.style.position = "fixed";
  temp.style.left = "-9999px";
  document.body.appendChild(temp);
  temp.select();
  try {
    document.execCommand("copy");
  } catch (e) {
    console.warn("Fallback copy failed:", e);
  }
  document.body.removeChild(temp);
}

copyDeckBtn.addEventListener("click", async () => {
  const text = buildPlainDecklistText();
  if (navigator.clipboard && navigator.clipboard.writeText) {
    try {
      await navigator.clipboard.writeText(text);
    } catch (err) {
      console.warn("Clipboard API failed, using fallback:", err);
      fallbackCopyToClipboard(text);
    }
  } else {
    fallbackCopyToClipboard(text);
  }
});

// --- 13) Start, reroll & restart -------------------------------

startBtn.addEventListener("click", () => {
  currentChoiceIndex = 0;
  selectedPacks = [];
  usedPackIds = new Set();
  lastOfferedPackIds = new Set();
  hideCardPreview();
  showPackChoices();
});

rerollBtn.addEventListener("click", () => {
  hideCardPreview();
  showPackChoices();
});

restartBtn.addEventListener("click", () => {
  currentChoiceIndex = 0;
  selectedPacks = [];
  usedPackIds = new Set();
  lastOfferedPackIds = new Set();
  decklistOutput.value = "";
  resultSection.style.display = "none";
  hideCardPreview();
  showPackChoices();
});

// --- 14) Init on load ------------------------------------------


initSetFilters();

